131	// ---- Order attribution (which orders came from a partner deep link) -------
132	
133	/** Known partner ids allowed to tag an order via ?ref= — anything else is dropped. */
134	export const PARTNER_IDS = ["kodely"] as const;
135	export type PartnerId = (typeof PARTNER_IDS)[number];
136	
137	export const PARTNER_SOURCE_COOKIE = "nx_partner_ref";
138	
139	/**
140	 * Read the partner-source cookie set by PartnerSourceCapture (a ?ref=kodely deep
141	 * link into /dashboard/deploy or /dashboard/domains). Used at ORDER-CREATION time
142	 * (payAndDeploy, purchaseDomain) to tag the Server/Domain row with `partnerSource`,
143	 * so the provision-success webhook (worker/index.ts, purchaseDomain) knows which
144	 * orders to notify the partner about — most orders are direct Nxeon customers and
145	 * must NEVER be forwarded to Kodely's webhook.
146	 */
147	export function partnerSourceFromCookie(jar: Awaited<ReturnType<typeof cookies>>): PartnerId | undefined {
148	  const v = jar.get(PARTNER_SOURCE_COOKIE)?.value;
149	  return (PARTNER_IDS as readonly string[]).includes(v ?? "") ? (v as PartnerId) : undefined;
150	}
